def merge_inventory(a: dict, b: dict) -> dict:
    """Merge two inventory dictionaries by summing quantities of shared keys.

    >>> merge_inventory({'apple': 2, 'pear': 1}, {'apple': 3, 'kiwi': 4})
    {'apple': 5, 'pear': 1, 'kiwi': 4}
    >>> merge_inventory({}, {'x': 7})
    {'x': 7}
    """
    result = dict(a)
    for key, value in b.items():
        if key in result:
            result[key] += value
        else:
            result[key] = value
    return result
```

