def parse_kv_lines(text: str) -> dict:
    """Parse lines of 'key=value' pairs into a dictionary.

    Blank lines are ignored. Keys and values are stripped of surrounding
    whitespace. Lines without '=' raise ValueError.

    Examples:
        >>> parse_kv_lines('a=1\nb = 2\n\n')
        {'a': '1', 'b': '2'}
        >>> parse_kv_lines('x=hello world')
        {'x': 'hello world'}
    """
    result = {}
    for line in text.splitlines():
        if not line.strip():
            continue
        if '=' not in line:
            raise ValueError(f"Line without '=': {line!r}")
        key, value = line.split('=', 1)
        result[key.strip()] = value.strip()
    return result
```

```python
def count_border_ones(grid: list[list[int]]) -> int:
    """Return the number of 1s on the border (outermost rows and columns) of a 2D grid.

    Examples:
        count_border_ones([[1, 0, 1], [0, 1, 0], [1, 0, 1]]) -> 4
        count_border_ones([[1, 1], [1, 1]]) -> 4
    """
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    count = 0

    for r in range(rows):
        for c in range(cols):
            if r == 0 or r == rows - 1 or c == 0 or c == cols - 1:
                if grid[r][c] == 1:
                    count += 1

    return count
```

```python
def count_stair_ways(n: int) -> int:
    """Return the number of distinct ways to climb n stairs when you can take
    1 or 2 steps at a time. Uses recursion with memoization (dynamic programming).

    Examples:
        count_stair_ways(3) == 3   # 111, 12, 21
        count_stair_ways(4) == 5   # 1111, 112, 121, 211, 22
    """
    memo = {}

    def helper(k: int) -> int:
        if k <= 0:
            return 1 if k == 0 else 0
        if k in memo:
            return memo[k]
        memo[k] = helper(k - 1) + helper(k - 2)
        return memo[k]

    return helper(n)
```

```python
def count_reachable(graph: dict, start: int) -> int:
    """Count the number of nodes reachable from start in an undirected graph.

    Examples:
        count_reachable({0: [1, 2], 1: [0], 2: [0], 3: []}, 0) == 3
        count_reachable({0: [1], 1: [0], 2: [3], 3: [2]}, 0) == 2
    """
    if start not in graph:
        return 0

    visited = set()
    stack = [start]

    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                stack.append(neighbor)

    return len(visited)
```

