def group_by_parity_sum(items: list) -> dict:
    """Group integers by parity and return a dict mapping 'even'/'odd' to the sum of their values.

    Only integer values are considered; non-integer entries are ignored.
    Keys with no matching integers should map to 0.

    Examples:
        group_by_parity_sum([1, 2, 3, 4]) == {'even': 6, 'odd': 4}
        group_by_parity_sum(['a', 5, 7.5, 8]) == {'even': 8, 'odd': 12}
    """
    result = {'even': 0, 'odd': 0}
    for item in items:
        if isinstance(item, int) and not isinstance(item, bool):
            if item % 2 == 0:
                result['even'] += item
            else:
                result['odd'] += item
    return result
```

```python
def triangle_area_perimeter(a: float, b: float, c: float) -> tuple:
    """Return (area, perimeter) of a triangle given its three side lengths.

    If the sides cannot form a valid triangle, return (0.0, 0.0).

    >>> triangle_area_perimeter(3, 4, 5)
    (6.0, 12)
    >>> triangle_area_perimeter(1, 2, 10)
    (0.0, 0.0)
    """
    if a <= 0 or b <= 0 or c <= 0:
        return (0.0, 0.0)
    if a + b <= c or a + c <= b or b + c <= a:
        return (0.0, 0.0)
    perimeter = a + b + c
    s = perimeter / 2
    area = (s * (s - a) * (s - b) * (s - c)) ** 0.5
    return (float(area), perimeter)
```

```python
def collapse_runs(s: str) -> str:
    """Collapse each maximal run of identical characters into a single character
    followed by the run length, but only if the run length is greater than 1;
    runs of length 1 are left unchanged.

    Examples:
        collapse_runs("aaabbc") == "a3b2c"
        collapse_runs("abc") == "abc"
    """
    if not s:
        return ""
    result = []
    i = 0
    n = len(s)
    while i < n:
        j = i + 1
        while j < n and s[j] == s[i]:
            j += 1
        count = j - i
        if count > 1:
            result.append(s[i] + str(count))
        else:
            result.append(s[i])
        i = j
    return "".join(result)
```

```python
def group_anagrams_by_length(words: list[str]) -> dict[int, list[list[str]]]:
    """Group words first by their length, then by whether they are anagrams of each other.

    Return a dict mapping each word length to a list of anagram groups. Within each
    length bucket, words that are anagrams of one another appear together in a
    sublist, and the sublists are ordered by their first appearance in `words`.
    Words within a sublist also keep their original relative order.

    Examples:
        >>> group_anagrams_by_length(['eat', 'tea', 'tan', 'ate', 'nat', 'bat'])
        {3: [['eat', 'tea', 'ate'], ['tan', 'nat'], ['bat']]}
        >>> group_anagrams_by_length(['ab', 'ba', 'abc', 'cab', 'xy'])
        {2: [['ab', 'ba'], ['xy']], 3: [['abc', 'cab']]}
    """
    result: dict[int, list[list[str]]] = {}
    for word in words:
        length = len(word)
        key = tuple(sorted(word))
        if length not in result:
            result[length] = []
        bucket = result[length]
        found = False
        for group in bucket:
            if tuple(sorted(group[0])) == key:
                group.append(word)
                found = True
                break
        if not found:
            bucket.append([word])
    return result
```

```python
def max_weight_path(grid: list[list[int]]) -> int:
    """Return the maximum sum of weights along a path from the top-left to the
    bottom-right cell, moving only right or down at each step.

    Examples:
        >>> max_weight_path([[1, 3, 1], [1, 5, 1], [4, 2, 1]])
        12
        >>> max_weight_path([[5]])
        5
    """
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    dp = [[0] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if r == 0 and c == 0:
                dp[r][c] = grid[r][c]
            elif r == 0:
                dp[r][c] = dp[r][c - 1] + grid[r][c]
            elif c == 0:
                dp[r][c] = dp[r - 1][c] + grid[r][c]
            else:
                dp[r][c] = max(dp[r - 1][c], dp[r][c - 1]) + grid[r][c]

    return dp[rows - 1][cols - 1]
```

```python
def consolidate_intervals(intervals: list[list[int]], merge_gap: int) -> dict:
    """Merge overlapping or near intervals and return a summary.

    Given a list of [start, end] integer intervals (inclusive), merge any
    intervals whose gap is at most merge_gap. Return a dict with keys:
      - 'merged': sorted list of merged [start, end] intervals
      - 'total_span': sum of (end - start + 1) over merged intervals
      - 'count': number of merged intervals

    Examples:
        >>> consolidate_intervals([[1,3],[2,5],[10,12]], 0)
        {'merged': [[1, 5], [10, 12]], 'total_span': 8, 'count': 2}
        >>> consolidate_intervals([[1,2],[4,5],[7,8]], 1)
        {'merged': [[1, 8]], 'total_span': 8, 'count': 1}
    """
    if not intervals:
        return {'merged': [], 'total_span': 0, 'count': 0}

    sorted_intervals = sorted([list(iv) for iv in intervals])
    merged = [sorted_intervals[0][:]]

    for start, end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end + merge_gap + 1:
            if end > last_end:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    total_span = sum(end - start + 1 for start, end in merged)

    return {
        'merged': merged,
        'total_span': total_span,
        'count': len(merged),
    }
```

