import re

def parse_wire_format(data: str) -> dict:
    """Parse a small wire format into a nested dictionary.

    Format rules:
      - Records are separated by ';' (semicolons). Empty records are ignored.
      - Each record is 'key=value' where key is [A-Za-z_][A-Za-z0-9_]*
        and value is either a bare token (no '=', ';', '[', ']', or whitespace)
        or a bracketed list like [a,b,c].
      - A bracketed list may contain bare tokens separated by commas;
        empty items between commas are allowed and become empty strings.
      - Whitespace around keys, values, brackets, and commas is stripped.
      - If the same key appears multiple times, later values overwrite earlier ones.
      - Malformed records raise ValueError with a message starting with 'bad record:'.

    Examples:
      >>> parse_wire_format('a=1; b=[x, y]; c = hello')
      {'a': '1', 'b': ['x', 'y'], 'c': 'hello'}
      >>> parse_wire_format('k=[]; k=[1,,2]')
      {'k': ['1', '', '2']}
    """
    result = {}
    key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    for raw in data.split(';'):
        record = raw.strip()
        if not record:
            continue
        if '=' not in record:
            raise ValueError(f"bad record: {record!r}")
        key_part, _, value_part = record.partition('=')
        key = key_part.strip()
        value_str = value_part.strip()

        if not key_re.match(key):
            raise ValueError(f"bad record: {record!r}")

        if value_str.startswith('['):
            if not value_str.endswith(']'):
                raise ValueError(f"bad record: {record!r}")
            inner = value_str[1:-1]
            items = []
            for item in inner.split(','):
                token = item.strip()
                if token == '':
                    items.append('')
                else:
                    if any(ch in token for ch in '=;[]') or any(c.isspace() for c in token):
                        raise ValueError(f"bad record: {record!r}")
                    items.append(token)
            # Handle empty list case: '[]' should give []
            if inner.strip() == '' and len(items) == 1 and items[0] == '':
                items = []
            result[key] = items
        elif value_str.startswith(']') or '[' in value_str or ']' in value_str:
            raise ValueError(f"bad record: {record!r}")
        else:
            if any(ch in value_str for ch in '=;[]') or any(c.isspace() for c in value_str):
                raise ValueError(f"bad record: {record!r}")
            result[key] = value_str

    return result
```

```python
def count_reachable_within_k_steps(graph: dict, start: int, k: int) -> list:
    """
    Given an undirected graph as an adjacency dictionary and a starting node,
    return the sorted list of nodes reachable from start in at most k steps.
    Nodes not present as keys are treated as having no outgoing edges.

    Examples:
    >>> count_reachable_within_k_steps({0: [1], 1: [0, 2], 2: [1]}, 0, 1)
    [0, 1]
    >>> count_reachable_within_k_steps({0: [1], 1: [0, 2], 2: [1]}, 0, 5)
    [0, 1, 2]
    """
    visited = {start}
    frontier = {start}
    for _ in range(k):
        next_frontier = set()
        for node in frontier:
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    next_frontier.add(neighbor)
        if not next_frontier:
            break
        frontier = next_frontier
    return sorted(visited)
```

