def parse_kv_lines(text: str) -> dict:
    """Parse a small text format of 'key=value' lines into a dict.

    Each non-empty line must contain exactly one '=' separating a key and
    a value. Leading/trailing whitespace on keys and values is stripped.
    Empty lines are ignored. If a key appears more than once, the last
    occurrence wins.

    Examples:
        >>> parse_kv_lines('a=1\nb = two \n\nc=3')
        {'a': '1', 'b': 'two', 'c': '3'}
        >>> parse_kv_lines('x = hello world\ny=')
        {'x': 'hello world', 'y': ''}
    """
    result = {}
    for line in text.splitlines():
        if not line.strip():
            continue
        key, sep, value = line.partition('=')
        if not sep:
            raise ValueError(f"Line missing '=': {line!r}")
        result[key.strip()] = value.strip()
    return result
```

