def group_by_parity_and_sort(words: list[str]) -> dict[str, list[str]]:
    """Group words by the parity of their length and sort each group.

    Returns a dict with keys 'even' and 'odd' (only if non-empty), where each
    value is the list of words whose length has that parity, sorted
    alphabetically. Words are compared case-insensitively for sorting but
    returned in their original form.

    Examples:
        >>> group_by_parity_and_sort(['apple', 'fig', 'kiwi', 'pear'])
        {'even': ['kiwi', 'pear'], 'odd': ['fig', 'apple']}
        >>> group_by_parity_and_sort([])
        {}
    """
    even = []
    odd = []
    for word in words:
        if len(word) % 2 == 0:
            even.append(word)
        else:
            odd.append(word)

    result = {}
    if even:
        result['even'] = sorted(even, key=str.lower)
    if odd:
        result['odd'] = sorted(odd, key=str.lower)
    return result
```

