def parse_kv_log(text: str) -> dict[str, list[dict[str, str]]]:
    """Parse a small key=value log format grouped by section headers.

    Lines starting with '[' and ending with ']' define a section name.
    Other non-empty lines are comma-separated key=value pairs (no spaces
    around '='). Values may be quoted with double quotes; unquoted values
    are stripped of surrounding whitespace. Blank lines are ignored.
    Pairs before any section belong to the section named ''.

    Example 1:
        parse_kv_log('[a]\nx=1, y="hi, there"\n[b]\nz=3')
        == {'a': [{'x': '1', 'y': 'hi, there'}], 'b': [{'z': '3'}]}

    Example 2:
        parse_kv_log('k=v\n[s]\na=b')
        == {'': [{'k': 'v'}], 's': [{'a': 'b'}]}
    """
    result: dict[str, list[dict[str, str]]] = {}
    current_section = ""

    def split_pairs(line: str):
        pairs = []
        buf = []
        in_quotes = False
        for ch in line:
            if ch == '"':
                in_quotes = not in_quotes
                buf.append(ch)
            elif ch == ',' and not in_quotes:
                pairs.append(''.join(buf))
                buf = []
            else:
                buf.append(ch)
        if buf:
            pairs.append(''.join(buf))
        return pairs

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        if line.startswith('[') and line.endswith(']'):
            current_section = line[1:-1]
            result.setdefault(current_section, [])
            continue
        entry: dict[str, str] = {}
        for pair in split_pairs(line):
            pair = pair.strip()
            if not pair or '=' not in pair:
                continue
            key, value = pair.split('=', 1)
            key = key.strip()
            value = value.strip()
            if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
                value = value[1:-1]
            entry[key] = value
        if entry:
            result.setdefault(current_section, []).append(entry)

    return result
```

```python
def count_paths_with_obstacles(grid: list[list[int]]) -> int:
    """Count the number of paths from top-left to bottom-right moving only right or down,
    where cells with value 1 are obstacles and cannot be entered.

    Examples:
        count_paths_with_obstacles([[0, 0,], [0, 0]]) returns 2
        count_paths_with_obstacles([[0, 1], [0, 0]]) returns 1
    """
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])

    if grid[0][0] == 1 or grid[rows - 1][cols - 1] == 1:
        return 0

    dp = [[0] * cols for _ in range(rows)]
    dp[0][0] = 1

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                dp[r][c] = 0
                continue
            if r > 0:
                dp[r][c] += dp[r - 1][c]
            if c > 0:
                dp[r][c] += dp[r][c - 1]

    return dp[rows - 1][cols - 1]
```

