```python
def count_reachable_within_steps(graph: dict, start: str, max_steps: int) -> int:
    """Count how many distinct nodes are reachable from start using at most max_steps edges.

    The graph is given as a dictionary mapping each node to a list of its neighbors.
    Nodes that appear only as neighbors are also valid nodes. The start node is
    always counted (it is reachable in 0 steps).

    Examples:
        >>> count_reachable_within_steps({'A': ['B', 'C'], 'B': ['D'], 'C': [], 'D': []}, 'A', 1)
        3
        >>> count_reachable_within_steps({'A': ['B'], 'B': ['C'], 'C': ['A']}, 'A', 5)
        3
    """
    if max_steps < 0:
        return 0

    visited = {start}
    frontier = [start]

    for _ in range(max_steps):
        next_frontier = []
        for node in frontier:
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    next_frontier.append(neighbor)
        if not next_frontier:
            break
        frontier = next_frontier

    return len(visited)
```

