def collapse_runs(s: str) -> str:
    """Collapse each maximal run of identical characters into a single character.

    Examples:
        collapse_runs("aaabbbcc") == "abc"
        collapse_runs("aabbccaabb") == "abca b"  # note: no spaces, see tests
    """
    if not s:
        return ""
    result = [s[0]]
    for ch in s[1:]:
        if ch != result[-1]:
            result.append(ch)
    return "".join(result)
