def parse_logfmt(text: str) -> dict:
    """Parse a small logfmt-like text format into a nested dictionary.

    The input consists of lines. Each line is either:
      - a section header: '[' name ']' (name has no brackets/whitespace)
      - a key/value pair: key '=' value, where value may be quoted with double quotes.
        Quoted values support escapes \\" and \\\\. Unquoted values run to the next space.
      - blank or whitespace-only lines are ignored.

    Keys before any section header go into the top-level dict. Pairs after a
    section header go into that section's dict. A repeated section merges keys;
    a repeated key within the same target overwrites. Malformed lines raise ValueError.

    Examples:
        parse_logfmt('a=1 b="x y"\n[s]\nc=2') == {'a': '1', 'b': 'x y', 's': {'c': '2'}}
        parse_logfmt('[s]\nk=v k=w') == {'s': {'k': 'w'}}
    """
    result = {}
    current = result

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue

        if line.startswith('['):
            # Section header
            if not line.endswith(']'):
                raise ValueError(f"Malformed section header: {raw_line!r}")
            name = line[1:-1]
            if not name or any(c in '[] \t' for c in name):
                raise ValueError(f"Invalid section name: {name!r}")
            if name not in result:
                result[name] = {}
            elif not isinstance(result[name], dict):
                # Overwrite non-dict entry with a dict
                result[name] = {}
            current = result[name]
            continue

        # Key/value pairs on this line
        i = 0
        n = len(line)
        while i < n:
            # Skip spaces between pairs
            while i < n and line[i] == ' ':
                i += 1
            if i >= n:
                break

            # Parse key
            key_start = i
            while i < n and line[i] not in '= ':
                i += 1
            if i >= n or line[i] != '=':
                raise ValueError(f"Malformed key/value pair in line: {raw_line!r}")
            key = line[key_start:i]
            if not key:
                raise ValueError(f"Empty key in line: {raw_line!r}")
            i += 1  # skip '='

            # Parse value
            if i < n and line[i] == '"':
                i += 1
                chars = []
                closed = False
                while i < n:
                    ch = line[i]
                    if ch == '\\' and i + 1 < n:
                        nxt = line[i + 1]
                        if nxt in ('"', '\\'):
                            chars.append(nxt)
                            i += 2
                            continue
                        else:
                            chars.append(ch)
                            i += 1
                            continue
                    elif ch == '"':
                        i += 1
                        closed = True
                        break
                    else:
                        chars.append(ch)
                        i += 1
                if not closed:
                    raise ValueError(f"Unterminated quoted value in line: {raw_line!r}")
                value = ''.join(chars)
            else:
                val_start = i
                while i < n and line[i] != ' ':
                    i += 1
                value = line[val_start:i]

            current[key] = value

    return result
```

```python
def process_orders(orders: list[tuple[str, int]]) -> list[int]:
    """Simulate a warehouse with a stack (LIFO) and queue (FIFO).

    Each order is a tuple (kind, value):
      - ('push', v): push v onto the stack.
      - ('enqueue', v): enqueue v into the queue.
      - ('pop', 0): pop from the stack; if empty, ignore.
      - ('dequeue', 0): dequeue from the queue; if empty, ignore.
      - ('transfer', k): move up to k items from the top of the stack to the back of the queue,
        one at a time (top first). If the stack empties first, stop.
      - ('flush', 0): repeatedly pop from the stack until it is empty.
    Return the list of values removed by 'pop' and 'dequeue' operations in order.

    Examples:
        >>> process_orders([('push', 1), ('push', 2), ('pop', 0)])
        [2]
        >>> process_orders([('enqueue', 5), ('push', 9), ('transfer', 1), ('dequeue', 0), ('dequeue', 1)])
        [9, 5]
    """
    from collections import deque

    stack = []
    queue = deque()
    result = []

    for kind, value in orders:
        if kind == 'push':
            stack.append(value)
        elif kind == 'enqueue':
            queue.append(value)
        elif kind == 'pop':
            if stack:
                result.append(stack.pop())
        elif kind == 'dequeue':
            if queue:
                result.append(queue.popleft())
        elif kind == 'transfer':
            for _ in range(value):
                if not stack:
                    break
                queue.append(stack.pop())
        elif kind == 'flush':
            while stack:
                stack.pop()

    return result
```

