def merge_inventory(records: list[dict]) -> dict:
    """Merge inventory records into a single summary dictionary.

    Each record is a dict with keys 'item' (str), 'qty' (int), and
    optionally 'tags' (list of str). For each item, sum the quantities.
    Also collect the union of all tags per item, sorted alphabetically,
    stored under key '<item>_tags'. Items with zero total quantity are
    omitted from the result. If no records, return {}.

    Examples:
        >>> merge_inventory([{'item': 'a', 'qty': 2}, {'item': 'a', 'qty': 3}])
        {'a': 5}
        >>> merge_inventory([{'item': 'x', 'qty': 1, 'tags': ['b', 'a']},
        ...                  {'item': 'x', 'qty': 0, 'tags': ['c']}])
        {'x': 1, 'x_tags': ['a', 'b', 'c']}
    """
    if not records:
        return {}

    totals = {}
    tags_map = {}

    for rec in records:
        item = rec['item']
        qty = rec.get('qty', 0)
        totals[item] = totals.get(item, 0) + qty

        if 'tags' in rec and rec['tags']:
            tags_map.setdefault(item, set()).update(rec['tags'])

    result = {}
    for item, total in totals.items():
        if total == 0:
            continue
        result[item] = total
        if item in tags_map:
            result[f'{item}_tags'] = sorted(tags_map[item])

    return result
