import re

def parse_kv_log(text: str) -> list[dict]:
    """Parse a small key=value log format into records.

    Each non-empty line is one record. Fields are separated by single spaces
    and each field has the form key=value where value may be quoted with
    double quotes to contain spaces. Quoted values support the escapes \\" 
    and \\\\. Lines beginning with '#' are comments and ignored. Keys must be
    non-empty identifiers ([A-Za-z_][A-Za-z0-9_]*). Return a list of dicts in
    order of appearance. Raise ValueError on malformed lines or duplicate keys
    within a record.

    Examples:
        parse_kv_log('a=1 b="x y"') == [{'a': '1', 'b': 'x y'}]
        parse_kv_log('# c\na=1\n\nb=2') == [{'a': '1'}, {'b': '2'}]
    """
    key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    records = []

    for raw_line in text.split('\n'):
        line = raw_line.strip()
        if not line:
            continue
        if line.startswith('#'):
            continue

        record = {}
        i = 0
        n = len(line)
        while i < n:
            # Parse key
            start = i
            while i < n and line[i] != '=' and line[i] != ' ':
                i += 1
            if i >= n or line[i] != '=':
                raise ValueError(f"Malformed line (missing '='): {raw_line!r}")
            key = line[start:i]
            if not key_re.match(key):
                raise ValueError(f"Invalid key {key!r} in line: {raw_line!r}")
            i += 1  # skip '='

            # Parse value
            if i < n and line[i] == '"':
                i += 1
                chars = []
                closed = False
                while i < n:
                    c = line[i]
                    if c == '\\':
                        if i + 1 < n and line[i + 1] in ('"', '\\'):
                            chars.append(line[i + 1])
                            i += 2
                            continue
                        else:
                            raise ValueError(
                                f"Invalid escape in line: {raw_line!r}"
                            )
                    elif c == '"':
                        i += 1
                        closed = True
                        break
                    else:
                        chars.append(c)
                        i += 1
                if not closed:
                    raise ValueError(
                        f"Unterminated quoted value in line: {raw_line!r}"
                    )
                value = ''.join(chars)
                # After closing quote, must be end or space
                if i < n and line[i] != ' ':
                    raise ValueError(
                        f"Unexpected character after quoted value in line: {raw_line!r}"
                    )
            else:
                start = i
                while i < n and line[i] != ' ':
                    i += 1
                value = line[start:i]

            if key in record:
                raise ValueError(
                    f"Duplicate key {key!r} in line: {raw_line!r}"
                )
            record[key] = value

            # Skip single space separator
            if i < n:
                if line[i] != ' ':
                    raise ValueError(f"Malformed line: {raw_line!r}")
                i += 1
                if i >= n:
                    raise ValueError(
                        f"Trailing space in line: {raw_line!r}"
                    )

        records.append(record)

    return records
```

