def group_anagrams_by_length(words: list[str]) -> dict[int, dict[str, list[str]]]:
    """Group words first by their length, then by their sorted-letter signature.

    Returns a nested dict where the outer keys are word lengths and the inner
    keys are alphabetically sorted versions of the words. Each innermost value
    is a list of the original words sharing that length and letter signature,
    preserving their original order of appearance. Words with no anagram
    partners still appear under their own signature.

    Examples:
        >>> group_anagrams_by_length(['cat', 'act', 'dog', 'tac', 'god'])
        {3: {'act': ['cat', 'act', 'tac'], 'dgo': ['dog', 'god']}}
        >>> group_anagrams_by_length(['ab', 'ba', 'abc'])
        {2: {'ab': ['ab', 'ba']}, 3: {'abc': ['abc']}}
    """
    result: dict[int, dict[str, list[str]]] = {}
    for word in words:
        length = len(word)
        signature = ''.join(sorted(word))
        if length not in result:
            result[length] = {}
        if signature not in result[length]:
            result[length][signature] = []
        result[length][signature].append(word)
    return result
```

