def merge_interval_records(records: list[dict]) -> dict:
    """Merge overlapping interval records grouped by category.

    Each record is a dict with keys 'category' (str), 'start' (int), and
    'end' (int), where start <= end. Intervals within the same category that
    overlap or touch (i.e., next.start <= current.end) must be merged into a
    single interval. The result maps each category to a sorted list of merged
    [start, end] pairs. Categories with no records are omitted.
    """
    grouped = {}
    for rec in records:
        grouped.setdefault(rec['category'], []).append((rec['start'], rec['end']))

    result = {}
    for category, intervals in grouped.items():
        intervals.sort()
        merged = []
        for start, end in intervals:
            if merged and start <= merged[-1][1]:
                if end > merged[-1][1]:
                    merged[-1][1] = end
            else:
                merged.append([start, end])
        result[category] = merged

    return result
```

