def count_rare_set_elements(sets: list[set[int]], k: int) -> dict[str, int]:
    """Given a list of sets and an integer k, return counts describing elements based on how many sets they appear in.

    Return a dict with keys:
      - 'unique': number of distinct elements appearing in exactly one set
      - 'common': number of distinct elements appearing in all sets
      - 'rare': number of distinct elements appearing in at least 1 but fewer than k sets
      - 'total': total number of distinct elements across all sets

    Examples:
        count_rare_set_elements([{1,2,3},{2,3,4},{3,4,5}], 2) == {'unique': 2, 'common': 1, 'rare': 3, 'total': 5}
        count_rare_set_elements([], 3) == {'unique': 0, 'common': 0, 'rare': 0, 'total': 0}
    """
    if not sets:
        return {'unique': 0, 'common': 0, 'rare': 0, 'total': 0}

    counts = {}
    for s in sets:
        for elem in s:
            counts[elem] = counts.get(elem, 0) + 1

    n = len(sets)
    unique = sum(1 for c in counts.values() if c == 1)
    common = sum(1 for c in counts.values() if c == n)
    rare = sum(1 for c in counts.values() if 1 <= c < k)
    total = len(counts)

    return {'unique': unique, 'common': common, 'rare': rare, 'total': total}
