    Each non-empty line is either a comment (starts with '#'), a section header
    of the form '[name]', or a 'key = value' pair. Keys in a section are stored
    under that section name; keys before any section go to the top level.
    Whitespace around keys and values is stripped. Values may be quoted with
    single or double quotes, in which case surrounding whitespace inside the
    quotes is preserved. Duplicate keys overwrite earlier ones.

    Examples:
        >>> parse_kv_config('a = 1\n[s]\nb = 2')
        {'a': '1', 's': {'b': '2'}}
        >>> parse_kv_config('# c\nx=" hi "\n[y]')
        {'x': ' hi ', 'y': {}}
    """
    result = {}
    current = result

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith('#'):
            continue

        if line.startswith('[') and line.endswith(']'):
            name = line[1:-1].strip()
            if name not in result or not isinstance(result[name], dict):
                result[name] = {}
            current = result[name]
            continue

        if '=' in line:
            key, _, value = line.partition('=')
            key = key.strip()
            value = value.strip()

            if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
