def group_by_parity_sum(items: list) -> dict:
    """Group integers from a list into two lists by parity, then return a dict
    mapping each parity key ('even'/'odd') to the sum of its numbers.

    Empty groups should map to 0. Non-integer values are ignored.

    Examples:
        >>> group_by_parity_sum([1, 2, 3, 4])
        {'even': 6, 'odd': 4}
        >>> group_by_parity_sum([])
        {'even': 0, 'odd': 0}
    """
    result = {'even': 0, 'odd': 0}
    for item in items:
        if isinstance(item, int) and not isinstance(item, bool):
            if item % 2 == 0:
                result['even'] += item
            else:
                result['odd'] += item
    return result
