def parse_ledger(text: str) -> dict:
    """Parse a small ledger text format into a structured dictionary.

    Format rules:
      - Lines are separated by '\n'. Blank lines and lines starting with '#' are ignored.
      - A section header is '[NAME]' on its own line; NAME is non-empty, no spaces.
      - Inside a section, each entry has form 'key = value' (spaces optional around '=').
      - Values may be quoted with double quotes to include spaces or '='; quotes must
        be balanced. Unquoted values cannot contain whitespace or '='.
      - Keys must match [A-Za-z_][A-Za-z0-9_]* and be unique within a section.
      - Entries before any section header raise ValueError.
      - Duplicate sections, duplicate keys, malformed lines, or unbalanced quotes
        raise ValueError.
      - The result maps section name -> dict of key -> value (strings).

    Examples:
        >>> parse_ledger('# c\n[main]\na = 1\nb="x y"')
        {'main': {'a': '1', 'b': 'x y'}}
        >>> parse_ledger('[s]\nk=v')
        {'s': {'k': 'v'}}
    """
    import re

    key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    result = {}
    current_section = None

    for raw_line in text.split('\n'):
        line = raw_line.strip()
        if not line or line.startswith('#'):
            continue

        # Section header
        if line.startswith('['):
            if not line.endswith(']') or len(line) < 3:
                raise ValueError(f"Malformed section header: {raw_line!r}")
            name = line[1:-1]
            if not name or any(c.isspace() for c in name):
                raise ValueError(f"Invalid section name: {name!r}")
            if name in result:
                raise ValueError(f"Duplicate section: {name!r}")
            result[name] = {}
            current_section = name
            continue

        # Entry line
        if current_section is None:
            raise ValueError(f"Entry before any section: {raw_line!r}")

        if '=' not in line:
            raise ValueError(f"Malformed entry (no '='): {raw_line!r}")

        eq_idx = line.index('=')
        key_part = line[:eq_idx].strip()
        value_part = line[eq_idx + 1:].strip()

        if not key_re.match(key_part):
            raise ValueError(f"Invalid key: {key_part!r}")

        if key_part in result[current_section]:
            raise ValueError(f"Duplicate key {key_part!r} in section {current_section!r}")

        # Parse value
        if value_part.startswith('"'):
            if len(value_part) < 2 or not value_part.endswith('"'):
                raise ValueError(f"Unbalanced quotes in value: {value_part!r}")
            inner = value_part[1:-1]
            if '"' in inner:
                raise ValueError(f"Unbalanced quotes in value: {value_part!r}")
            value = inner
        else:
            if '"' in value_part:
                raise ValueError(f"Unexpected quote in unquoted value: {value_part!r}")
            if any(c.isspace() for c in value_part) or '=' in value_part:
                raise ValueError(f"Invalid unquoted value: {value_part!r}")
            value = value_part

        result[current_section][key_part] = value

    return result
```

