    island_id = [[-1] * cols for _ in range(rows)]
    sizes = {}
    current_id = 0

    def dfs(r, c):
        stack = [(r, c)]
        island_id[r][c] = current_id
        size = 0
        while stack:
            x, y = stack.pop()
            size += 1
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == 1 and island_id[nx][ny] == -1:
                    island_id[nx][ny] = current_id
                    stack.append((nx, ny))
        return size

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and island_id[r][c] == -1:
                sizes[current_id] = dfs(r, c)
                current_id += 1

    if current_id == 0:
        return 1
    if current_id == 1 and all(grid[r][c] == 1 for r in range(rows) for c in range(cols)):
        return rows * cols

    best = max(sizes.values())

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                neighbor_ids = set()
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dx, c + dy
                    if 0 <= nr < rows and 0 <= nc < cols and island_id[nr][nc] != -1:
                        neighbor_ids.add(island_id[nr][nc])
                total = 1 + sum(sizes[i] for i in neighbor_ids)
                best = max(best, total)

    return best
```

```python
def format_validate_records(records: list[str], width: int, fill: str = '.') -> list[str]:
    """Validate and reformat fixed-width record strings.

    Each input string must be non-empty, contain only printable ASCII characters,
    and have a length that is a multiple of `width`. Records are split into
    chunks of exactly `width` characters. Each chunk is right-aligned in a field
    of size `width + 2`, padded on the left with `fill` (which must be a single
    character). Invalid records raise ValueError with a message describing the
    first problem encountered; validation happens before any formatting.

    Examples:
        >>> format_validate_records(['abcde', 'fghij'], 5)
        ['..abcde', '..fghij']
        >>> format_validate_records(['ab', 'cd'], 2, '*')
        ['**ab', '**cd']
    """
    if not isinstance(width, int) or width <= 0:
        raise ValueError("width must be a positive integer")
    if not isinstance(fill, str) or len(fill) != 1:
        raise ValueError("fill must be a single character")

    for i, record in enumerate(records):
        if not isinstance(record, str):
            raise ValueError(f"record {i} is not a string")
        if len(record) == 0:
            raise ValueError(f"record {i} is empty")
        for ch in record:
            if not (32 <= ord(ch) <= 126):
                raise ValueError(
                    f"record {i} contains non-printable-ASCII character {ch!r}"
                )
        if len(record) % width != 0:
            raise ValueError(
                f"record {i} has length {len(record)} which is not a multiple of {width}"
            )

    result = []
    for record in records:
        for start in range(0, len(record), width):
            chunk = record[start:start + width]
            result.append(chunk.rjust(width + 2, fill))
    return result
```

