def count_reachable(graph: dict, start: int) -> int:
    """Return the number of nodes reachable from start in an undirected graph.

    The graph is given as a dictionary mapping each node to a list of its neighbors.
    Nodes that appear only as neighbors are also considered part of the graph.

    Examples:
        count_reachable({0: [1, 2], 1: [0], 2: [0]}, 0) == 3
        count_reachable({0: [1], 1: [0], 2: [3], 3: [2]}, 0) == 2
    """
    if start not in graph and not any(start in neighbors for neighbors in graph.values()):
        return 0

    visited = set()
    stack = [start]

    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                stack.append(neighbor)

    return len(visited)
