def merge_inventory(records: list[dict]) -> dict:
    """Merge a list of inventory record dicts into one summary dict.

    Each record has keys 'item' (str), 'qty' (int), and optionally 'tags'
    (list of str). The result maps each item to a dict with 'total' (sum of
    qty across records for that item) and 'tags' (sorted list of unique tags
    from all records for that item). Items missing from every record's tags
    get an empty tag list. Records with non-positive qty are ignored entirely.

    Examples:
        >>> merge_inventory([{'item': 'a', 'qty': 2, 'tags': ['x']},
        ...                  {'item': 'a', 'qty': 3, 'tags': ['y', 'x']}])
        {'a': {'total': 5, 'tags': ['x', 'y']}}
        >>> merge_inventory([{'item': 'b', 'qty': 0}, {'item': 'c', 'qty': 1}])
        {'c': {'total': 1, 'tags': []}}
    """
    summary = {}
    for record in records:
        qty = record.get('qty', 0)
        if qty <= 0:
            continue
        item = record['item']
        if item not in summary:
            summary[item] = {'total': 0, 'tags': set()}
        summary[item]['total'] += qty
        for tag in record.get('tags', []) or []:
            summary[item]['tags'].add(tag)

    return {
        item: {'total': data['total'], 'tags': sorted(data['tags'])}
        for item, data in summary.items()
    }
