def merge_inventory(records: list[dict]) -> dict:
    """Merge inventory records into a single summary dict.

    Each record is a dict with keys 'item' (str) and 'qty' (int).
    Return a dict mapping each item to the total quantity across all records,
    sorted by item name. Items with zero or negative totals are omitted.

    Examples:
        >>> merge_inventory([{'item': 'a', 'qty': 2}, {'item': 'b', 'qty': 1}, {'item': 'a', 'qty': 3}])
        {'a': 5, 'b': 1}
        >>> merge_inventory([{'item': 'x', 'qty': 4}, {'item': 'x', 'qty': -4}, {'item': 'y', 'qty': 2}])
        {'y': 2}
    """
    totals = {}
    for record in records:
        item = record['item']
        totals[item] = totals.get(item, 0) + record['qty']
    return {item: totals[item] for item in sorted(totals) if totals[item] > 0}
