def parse_kv_config(text: str) -> dict:
    """Parse a small key-value configuration format.

    Lines contain KEY=VALUE pairs. Blank lines and lines starting with '#'
    are ignored. Keys and values are stripped of surrounding whitespace.
    Values may be quoted with single or double quotes, in which case the
    quotes are removed and inner whitespace is preserved. A trailing '# '
    comment outside of quotes is also stripped. Duplicate keys keep the last
    value. Malformed lines (no '=' or empty key) raise ValueError.

    Examples:
        >>> parse_kv_config('a = 1\nb=hello world\n# note\n')
        {'a': '1', 'b': 'hello world'}
        >>> parse_kv_config("name = 'Ada Lovelace'\ncity=\"New York\" # home")
        {'name': 'Ada Lovelace', 'city': 'New York'}
    """
    result = {}
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"Malformed line (missing '='): {raw_line!r}")
        key, _, value = line.partition('=')
        key = key.strip()
        if not key:
            raise ValueError(f"Malformed line (empty key): {raw_line!r}")
        value = value.strip()

        # Handle quoted values
        if value and value[0] in ("'", '"'):
            quote = value[0]
            end = value.find(quote, 1)
            if end == -1:
                # Unterminated quote; treat rest as value without quotes
                value = value[1:]
            else:
                value = value[1:end]
        else:
            # Strip trailing comment (only when preceded by whitespace)
            idx = None
            i = 0
            while i < len(value):
                if value[i] == '#' and (i == 0 or value[i-1].isspace()):
                    idx = i
                    break
                i += 1
            if idx is not None:
                value = value[:idx].rstrip()

        result[key] = value
    return result
