def parse_config(text: str) -> dict:
    """Parse a small indentation-based config format into nested dicts.

    Each non-empty line is either a section header ending with ':' or a
    key=value pair. Sections nest by indentation (spaces only). Values are
    parsed as int if they match an integer, true/false for booleans, and
    otherwise kept as stripped strings. Duplicate keys raise ValueError,
    as do tabs in indentation, inconsistent dedents, and malformed lines.

    Examples:
        >>> parse_config('a:\n  x=1\n  y=true\nb=hello')
        {'a': {'x': 1, 'y': True}, 'b': 'hello'}
        >>> parse_config('root:\n  child:\n    n=-3')
        {'root': {'child': {'n': -3}}}
    """
    def parse_value(s: str):
        s = s.strip()
        if s == "true":
            return True
        if s == "false":
            return False
        try:
            return int(s)
        except ValueError:
            return s

    root = {}
    # stack of (indent_level, dict)
    stack = [(-1, root)]
    seen_keys = [set()]

    for raw_line in text.splitlines():
        if not raw_line.strip():
            continue

        # Check for tabs in leading whitespace
        stripped = raw_line.lstrip(" ")
        indent_str = raw_line[: len(raw_line) - len(stripped)]
        if "\t" in indent_str or (stripped and raw_line[len(indent_str)] == "\t"):
            raise ValueError("Tabs in indentation are not allowed")
        if "\t" in raw_line[: len(raw_line) - len(raw_line.lstrip())]:
            raise ValueError("Tabs in indentation are not allowed")

        indent = len(indent_str)
        content = stripped.rstrip()

        # Pop stack to find correct parent based on indentation
        while stack and stack[-1][0] >= indent:
            stack.pop()
            seen_keys.pop()

        if not stack:
            raise ValueError(f"Inconsistent dedent at line: {raw_line!r}")

        parent_indent, parent = stack[-1]
        current_keys = seen_keys[-1]

        if content.endswith(":"):
            name = content[:-1].strip()
            if not name:
                raise ValueError(f"Malformed section header: {raw_line!r}")
            if name in current_keys:
                raise ValueError(f"Duplicate key: {name!r}")
            new_dict = {}
            parent[name] = new_dict
            current_keys.add(name)
            stack.append((indent, new_dict))
            seen_keys.append(set())
        else:
            if "=" not in content:
                raise ValueError(f"Malformed line: {raw_line!r}")
            key, _, value = content.partition("=")
            key = key.strip()
            if not key:
                raise ValueError(f"Malformed line (empty key): {raw_line!r}")
            if key in current_keys:
                raise ValueError(f"Duplicate key: {key!r}")
            parent[key] = parse_value(value)
            current_keys.add(key)

    return root
```

```python
def process_warehouse(ops: list[str]) -> list[int]:
    """Simulate a warehouse with two stacks (in and out) and a queue-like output.

    Operations:
      'push X'   : push integer X onto the input stack
      'pop'      : pop from the output stack; if empty, transfer all from input
                   stack to output stack first (reversing order), then pop.
                   If both empty, record -1.
      'peek'     : like pop but does not remove; record value or -1.
      'size'     : record total number of elements currently stored.
      'flush'    : transfer all input-stack elements to output stack, then
                   record all elements that would be popped in order until
                   empty. This empties the structure.

    Return the list of recorded values for pop/peek/size/flush operations.

    Examples:
        >>> process_warehouse(['push 1', 'push 2', 'pop', 'peek', 'size'])
        [1, 2, 1]
        >>> process_warehouse(['push 5', 'flush', 'pop'])
        [5, -1]
    """
    in_stack = []
    out_stack = []
    result = []

    def transfer():
        while in_stack:
            out_stack.append(in_stack.pop())

    for op in ops:
        parts = op.split()
        cmd = parts[0]

        if cmd == 'push':
            in_stack.append(int(parts[1]))
        elif cmd == 'pop':
            if not out_stack:
                transfer()
            if out_stack:
                result.append(out_stack.pop())
            else:
                result.append(-1)
        elif cmd == 'peek':
            if not out_stack:
                transfer()
            if out_stack:
                result.append(out_stack[-1])
            else:
                result.append(-1)
        elif cmd == 'size':
            result.append(len(in_stack) + len(out_stack))
        elif cmd == 'flush':
            transfer()
            while out_stack:
                result.append(out_stack.pop())

    return result
```

