def count_reachable(graph: dict, start: int) -> int:
    """Count the number of nodes reachable from start in an undirected graph.

    The graph is given as a dictionary mapping each node to a list of its neighbors.
    Nodes that appear only as neighbors are also considered part of the graph.
    The start node itself counts if it exists in the graph.

    Examples:
        count_reachable({1: [2], 2: [1, 3], 3: [2]}, 1) == 3
        count_reachable({1: [2], 2: [1], 3: [4], 4: [3]}, 1) == 2
    """
    # Build adjacency including neighbor-only nodes
    adj = {}
    for node, neighbors in graph.items():
        adj.setdefault(node, set()).update(neighbors)
        for n in neighbors:
            adj.setdefault(n, set()).add(node)

    if start not in adj:
        return 0

    visited = set()
    stack = [start]
    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        for neighbor in adj.get(node, ()):
            if neighbor not in visited:
                stack.append(neighbor)

    return len(visited)
