def merge_intervals_text(s: str) -> str:
    """Given a string of comma-separated integer intervals like '1-3,5-7,6-8',
    merge overlapping or adjacent intervals and return them sorted as a
    comma-separated string in the same format.

    Examples:
        merge_intervals_text('1-3,5-7,6-8') == '1-3,5-8'
        merge_intervals_text('10-12,1-2,3-4') == '1-4,10-12'
    """
    if not s.strip():
        return ""

    intervals = []
    for part in s.split(','):
        part = part.strip()
        if not part:
            continue
        if '-' in part:
            start_str, end_str = part.split('-', 1)
            start, end = int(start_str), int(end_str)
        else:
            start = end = int(part)
        if start > end:
            start, end = end, start
        intervals.append((start, end))

    if not intervals:
        return ""

    intervals.sort()

    merged = [list(intervals[0])]
    for start, end in intervals[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end + 1:
            merged[-1][1] = max(last_end, end)
        else:
            merged.append([start, end])

    result_parts = []
    for start, end in merged:
        if start == end:
            result_parts.append(str(start))
        else:
            result_parts.append(f"{start}-{end}")

    return ",".join(result_parts)
