def group_by_parity_sum(items: list) -> dict:
    """Group integers by parity and compute the sum of each group.

    Given a list of integers, return a dictionary with keys 'even' and 'odd',
    where each value is the sum of the numbers in that category. If a category
    has no elements, its sum should be 0.

    Examples:
        >>> group_by_parity_sum([1, 2, 3, 4])
        {'even': 6, 'odd': 4}
        >>> group_by_parity_sum([])
        {'even': 0, 'odd': 0}
    """
    result = {'even': 0, 'odd': 0}
    for n in items:
        if n % 2 == 0:
            result['even'] += n
        else:
            result['odd'] += n
    return result
