def count_squarefree_in_range(a: int, b: int) -> int:
    """Count integers n in [a, b] that are squarefree (not divisible by any perfect square > 1).

    Examples:
        count_squarefree_in_range(1, 10) == 7  # 1,2,3,5,6,7,10
        count_squarefree_in_range(4, 4) == 0   # 4 = 2^2
    """
    if a > b:
        return 0

    limit = int(b ** 0.5)
    while (limit + 1) * (limit + 1) <= b:
        limit += 1
    while limit * limit > b:
        limit -= 1

    # Mobius-like inclusion-exclusion using squares of primes up to sqrt(b).
    # Compute Möbius values for 1..limit via sieve.
    mu = [1] * (limit + 1)
    is_prime = [True] * (limit + 1)
    primes = []
    for i in range(2, limit + 1):
        if is_prime[i]:
            primes.append(i)
            mu[i] = -1
        for p in primes:
            if i * p > limit:
                break
            is_prime[i * p] = False
            if i % p == 0:
                mu[i * p] = 0
                break
            else:
                mu[i * p] = -mu[i]

    def count_upto(n: int) -> int:
        if n < 1:
            return 0
        total = 0
        k = 1
        while k * k <= n:
            total += mu[k] * (n // (k * k))
            k += 1
        return total

    return count_upto(b) - count_upto(a - 1)
```

