def parse_kv_log(text: str) -> dict[str, list[tuple[int, str]]]:
    """Parse a small key-value log format.

    Each non-empty line has the form ``<index>:<key>=<value>`` where index is a
    positive integer, key contains no spaces or '=' characters, and value may
    contain any characters except newlines. Lines whose index is not a valid
    positive integer are ignored. Return a dict mapping each key to a list of
    (index, value) tuples sorted by index ascending.

    Examples:
        >>> parse_kv_log('1:a=hello\n2:b=world\n3:a=again')
        {'a': [(1, 'hello'), (3, 'again')], 'b': [(2, 'world')]}
        >>> parse_kv_log('x:a=bad\n5:c=ok')
        {'c': [(5, 'ok')]}
    """
    result: dict[str, list[tuple[int, str]]] = {}
    for line in text.split('\n'):
        if not line:
            continue
        colon = line.find(':')
        if colon == -1:
            continue
        idx_str = line[:colon]
        rest = line[colon + 1:]
        try:
            idx = int(idx_str)
        except ValueError:
            continue
        if idx <= 0 or idx_str.strip() != idx_str or not idx_str.lstrip('+').isdigit():
            # ensure it's a plain positive integer representation
            if not (idx_str.isdigit() and idx > 0):
                continue
        eq = rest.find('=')
        if eq == -1:
            continue
        key = rest[:eq]
        value = rest[eq + 1:]
        if not key or ' ' in key or '=' in key:
            continue
        result.setdefault(key, []).append((idx, value))
    for k in result:
        result[k].sort(key=lambda t: t[0])
    return result
```

```python
def format_phone(number: str, style: str = "dash") -> str:
    """Validate a US phone number and format it according to style.

    Accepts 10 digits, optionally with spaces, dashes, dots, parentheses,
    or a leading +1. Raises ValueError if the number is invalid.
    Styles: "dash" -> 123-456-7890, "dot" -> 123.456.7890,
    "paren" -> (123) 456-7890, "plain" -> 1234567890.

    >>> format_phone("(123) 456-7890")
    '123-456-7890'
    >>> format_phone("+1 123.456.7890", "paren")
    '(123) 456-7890'
    """
    if not isinstance(number, str):
        raise ValueError("Phone number must be a string")

    s = number.strip()
    if s.startswith("+"):
        if not s.startswith("+1"):
            raise ValueError(f"Invalid phone number: {number!r}")
        s = s[2:]
    elif s.startswith("1") and len(s.replace(" ", "").replace("-", "").replace(".", "").replace("(", "").replace(")", "")) == 11:
        s = s[1:]

    allowed = set("0123456789 -.()")
    for ch in s:
        if ch not in allowed:
            raise ValueError(f"Invalid character in phone number: {ch!r}")

    digits = [c for c in s if c.isdigit()]
    if len(digits) != 10:
        raise ValueError(f"Phone number must contain exactly 10 digits: {number!r}")

    # Validate basic parenthesis structure if present
    if "(" in s or ")" in s:
        if s.count("(") != 1 or s.count(")") != 1:
            raise ValueError(f"Invalid parenthesis usage: {number!r}")
        if s.index("(") > s.index(")"):
            raise ValueError(f"Invalid parenthesis order: {number!r}")

    area = "".join(digits[0:3])
    prefix = "".join(digits[3:6])
    line = "".join(digits[6:10])

    if style == "dash":
        return f"{area}-{prefix}-{line}"
    elif style == "dot":
        return f"{area}.{prefix}.{line}"
    elif style == "paren":
        return f"({area}) {prefix}-{line}"
    elif style == "plain":
        return f"{area}{prefix}{line}"
    else:
        raise ValueError(f"Unknown style: {style!r}")
```

