def count_ways(n: int, steps: list) -> int:
    """Count the number of distinct ordered ways to reach exactly n using given step sizes.

    Examples:
        count_ways(4, [1, 2]) == 5   # 1111, 112, 121, 211, 22
        count_ways(3, [1, 3]) == 2   # 111, 3
    """
    if n < 0:
        return 0
    if n == 0:
        return 1

    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        for step in steps:
            if step <= i:
                dp[i] += dp[i - step]

    return dp[n]
```

