def consolidate_transactions(transactions: list[dict]) -> dict:
    """Consolidate a list of transaction records into per-account summaries.

    Each transaction is a dict with keys 'account' (str), 'type' (either
    'credit' or 'debit'), and 'amount' (int). Return a dict mapping each
    account to a summary dict with keys 'balance' (credits minus debits),
    'count' (total number of transactions), and 'largest_debit' (the largest
    debit amount for that account, or 0 if there are no debits).

    Example 1:
        consolidate_transactions([
            {'account': 'A', 'type': 'credit', 'amount': 10},
            {'account': 'A', 'type': 'debit', 'amount': 3},
        ]) == {'A': {'balance': 7, 'count': 2, 'largest_debit': 3}}

    Example 2:
        consolidate_transactions([]) == {}
    """
    result = {}
    for txn in transactions:
        account = txn['account']
        if account not in result:
            result[account] = {'balance': 0, 'count': 0, 'largest_debit': 0}
        summary = result[account]
        summary['count'] += 1
        if txn['type'] == 'credit':
            summary['balance'] += txn['amount']
        else:  # debit
            summary['balance'] -= txn['amount']
            if txn['amount'] > summary['largest_debit']:
                summary['largest_debit'] = txn['amount']
    return result
