```python
def process_orders(orders: list) -> list:
    """Simulate a warehouse with two queues (normal and priority) and a stack for returns.

    Each order is a tuple (type, id). Types:
      - ('add', id): append id to the normal queue.
      - ('vip', id): append id to the priority queue.
      - ('ship', None): if priority queue non-empty, pop its front; else pop normal queue front;
        push the shipped id onto the return stack. If both empty, do nothing.
      - ('return', None): if return stack non-empty, pop the top id and append it to the
        normal queue (restock). Otherwise do nothing.
      - ('peek', None): record the next id that would be shipped (priority first), or None
        if both queues are empty, without modifying anything.

    Return a list of results from 'peek' operations in order.

    Example 1:
        >>> process_orders([('add', 1), ('vip', 2), ('peek', None), ('ship', None), ('peek', None)])
        [2, 1]

    Example 2:
        >>> process_orders([('add', 5), ('ship', None), ('return', None), ('peek', None)])
        [5]
    """
    from collections import deque

    normal = deque()
    priority = deque()
    returns = []
    results = []

    for op, oid in orders:
        if op == 'add':
            normal.append(oid)
        elif op == 'vip':
            priority.append(oid)
        elif op == 'ship':
            if priority:
                shipped = priority.popleft()
            elif normal:
                shipped = normal.popleft()
            else:
                continue
            returns.append(shipped)
        elif op == 'return':
            if returns:
                normal.append(returns.pop())
        elif op == 'peek':
            if priority:
                results.append(priority[0])
            elif normal:
                results.append(normal[0])
            else:
                results.append(None)

    return results
```

```python
def min_enclosing_circle(points: list[tuple[float, float]]) -> tuple[float, float, float]:
    """Return the smallest enclosing circle of a set of 2D points as (cx, cy, r).

    Uses Welzl's randomized incremental algorithm. The result is exact up to
    floating point tolerance; ties are resolved deterministically by sorting.

    Examples:
        >>> min_enclosing_circle([(0, 0), (1, 0), (0, 1)])
        (0.5, 0.5, ~0.7071...)
        >>> min_enclosing_circle([(2, 3)])
        (2.0, 3.0, 0.0)
    """
    import math

    pts = sorted(set((float(x), float(y)) for x, y in points))
    if not pts:
        return (0.0, 0.0, -1.0)  # empty set: degenerate circle
    if len(pts) == 1:
        return (pts[0][0], pts[0][1], 0.0)

    def circle_from_2(a, b):
        cx = (a[0] + b[0]) / 2.0
        cy = (a[1] + b[1]) / 2.0
        r = math.hypot(a[0] - b[0], a[1] - b[1]) / 2.0
        return (cx, cy, r)

    def circle_from_3(a, b, c):
        ax, ay = a
        bx, by = b
        cx_, cy_ = c
        d = 2.0 * (ax * (by - cy_) + bx * (cy_ - ay) + cx_ * (ay - by))
        if abs(d) < 1e-18:
            # collinear: use farthest pair
            cands = [circle_from_2(a, b), circle_from_2(a, c), circle_from_2(b, c)]
            return max(cands, key=lambda t: t[2])
        ux = ((ax * ax + ay * ay) * (by - cy_) +
              (bx * bx + by * by) * (cy_ - ay) +
              (cx_ * cx_ + cy_ * cy_) * (ay - by)) / d
        uy = ((ax * ax + ay * ay) * (cx_ - bx) +
              (bx * bx + by * by) * (ax - cx_) +
              (cx_ * cx_ + cy_ * cy_) * (bx - ax)) / d
        r = math.hypot(ux - ax, uy - ay)
        return (ux, uy, r)

    def in_circle(pt, circ):
        dx = pt[0] - circ[0]
        dy = pt[1] - circ[1]
        return dx * dx + dy * dy <= circ[2] * circ[2] + 1e-12 * max(1.0, circ[2] * circ[2])

    def trivial(R):
        if not R:
            return (0.0, 0.0, -1.0)
        if len(R) == 1:
            return (R[0][0], R[0][1], 0.0)
        if len(R) == 2:
            return circle_from_2(R[0], R[1])
        return circle_from_3(R[0], R[1], R[2])

    def welzl(P, R, n):
        if n == 0 or len(R) == 3:
            return trivial(R)
        p = P[n - 1]
        D = welzl(P, R, n - 1)
        if in_circle(p, D):
            return D
        return welzl(P, R + [p], n - 1)

    import sys
    old_limit = sys.getrecursionlimit()
    try:
        sys.setrecursionlimit(max(old_limit, len(pts) * 4 + 100))
        # Deterministic shuffle via sorting already done; use fixed permutation
        shuffled = list(pts)
        # Fisher-Yates with deterministic seed based on data
        seed = 123456789
        for i in range(len(shuffled) - 1, 0, -1):
            seed = (1103515245 * seed + 12345) & 0x7fffffff
            j = seed % (i + 1)
            shuffled[i], shuffled[j] = shuffled[j], shuffled[i]
        return welzl(shuffled, [], len(shuffled))
    finally:
        sys.setrecursionlimit(old_limit)
```

```python
def group_by_length(words: list[str]) -> dict[int, list[str]]:
    """Group words by their lengths.

    Returns a dictionary mapping each word length to the list of words
    (in original order) that have that length.

    Examples:
        >>> group_by_length(['a', 'bb', 'cc', 'd'])
        {1: ['a', 'd'], 2: ['bb', 'cc']}
        >>> group_by_length([])
        {}
    """
    result: dict[int, list[str]] = {}
    for word in words:
        length = len(word)
        if length not in result:
            result[length] = []
        result[length].append(word)
    return result
```

