def count_reachable(graph: dict, start: int) -> int:
    """Return the number of nodes reachable from start in an undirected graph.

    graph maps each node to a list of its neighbors. The start node is
    included in the count if it appears in the graph.

    Examples:
        count_reachable({0: [1, 2], 1: [0], 2: [0], 3: []}, 0) == 3
        count_reachable({0: [1], 1: [0, 2], 2: [1]}, 2) == 3
    """
    if start not in graph:
        return 0

    visited = set()
    stack = [start]

    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                stack.append(neighbor)

    return len(visited)
```
